// Inspect generated bytes with the application's bundled importer; stdin only.
const alpha = require('../../RiffLoop/Resources/GpWeb/alphaTab.min.js');
const input = JSON.parse(require('node:fs').readFileSync(0, 'utf8'));
const settings = new alpha.Settings();
function snapshot(base64) {
    const score = alpha.importer.ScoreLoader.loadScoreFromBytes(Buffer.from(base64, 'base64'), settings);
    return {
        title: score.title,
        tempo: score.tempo,
        time: score.masterBars.map(bar => [bar.timeSignatureNumerator, bar.timeSignatureDenominator]),
        // Start and end are nominal score ticks, not a proof of audible playback.
        masterBarTicks: score.masterBars.map(bar => [bar.start, bar.start + bar.calculateDuration()]),
        tracks: score.tracks.map(track => track.staves.map(staff => ({
            tuning: Array.from(staff.stringTuning.tunings),
            transposition: staff.displayTranspositionPitch,
            bars: staff.bars.map(bar => bar.voices.map(voice => voice.beats.map(beat => ({
                duration: beat.duration,
                dots: beat.dots,
                tuplets: [beat.tupletNumerator, beat.tupletDenominator],
                playbackTicks: [beat.playbackStart, beat.playbackDuration],
                displayTicks: [beat.displayStart, beat.displayDuration],
                notes: beat.notes.map(note => ({ string: note.string, fret: note.fret,
                    realValue: note.realValue, accidentalMode: note.accidentalMode }))
            }))))
        })))
    };
}
process.stdout.write(JSON.stringify(input.map(snapshot)));
